function mkQs(l){const n=l.kind==='test'?20:l.kind==='speed'?80:l.kind==='trace'?6:10,F=l.focus,P=PT[l.kind],bag=sh(F),qs=[];
for(let k=0;k<n;k++){let x=bag[k%bag.length];if(l.kind==='review'||l.kind==='test'||l.kind==='speed'){const a=F[rnd(F.length)],b=F[rnd(F.length)];x=wt(a)>=wt(b)?a:b}
let t=P[k%P.length];if(x.amb&&t===2)t=0;if(t===3&&!STROKES[x.ch])t=0;if(t===5&&!x.parts)t=2;if(t===4&&(!x.syl||x.syl.length<2))t=2;if(t===3&&l.kind==='speed')t=0;const q={t,it:x};
if(t===4){let a=sh(x.syl),g=0;while(a.join('')===x.ch&&g++<9)a=sh(x.syl);q.tiles=a;q.need=a.length;q.tg=x.ch.replace(/ /g,'')}
else if(t===5){const pc=x.parts,ex=sh(ALLJ.filter(c=>!pc.includes(c))).slice(0,2);q.tiles=sh([...pc,...ex]);q.need=pc.length;q.tg=pc.join('')}else if(t<3)q.o=sh([x,...sh(l.pool.filter(p=>!!p.w===!!x.w&&p.ch!==x.ch&&lab(p)!==lab(x)&&!(t===2&&(p.amb||p.say===x.say)))).slice(0,3)]);qs.push(q)}return qs}
