let AC,MB,RV;
function actx(){if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();MB=AC.createGain();MB.gain.value=.85;const cp=AC.createDynamicsCompressor();MB.connect(cp);cp.connect(AC.destination);RV=AC.createConvolver();const n=AC.sampleRate*1.3|0,b=AC.createBuffer(2,n,AC.sampleRate);for(let c=0;c<2;c++){const d=b.getChannelData(c);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,2.8)}RV.buffer=b;const g=AC.createGain();g.gain.value=.3;RV.connect(g);g.connect(MB)}if(AC.state==='suspended')AC.resume();return AC}
const nt=(f,d=.2,o={})=>{if(!S.sfx)return;try{const a=actx(),t=a.currentTime+(o.at||0),os=a.createOscillator(),g=a.createGain(),fl=a.createBiquadFilter();os.type=o.type||'sine';os.frequency.setValueAtTime(f,t);if(o.to)os.frequency.exponentialRampToValueAtTime(o.to,t+d);fl.type='lowpass';fl.frequency.value=o.lp||6000;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(o.v||.12,t+(o.a||.006));g.gain.exponentialRampToValueAtTime(.0001,t+d);os.connect(fl);fl.connect(g);g.connect(MB);if(o.rv)g.connect(RV);os.start(t);os.stop(t+d+.05)}catch(e){}};
const bl=(f,d,o={})=>{nt(f,d,{...o,rv:1});nt(f*2.76,d*.45,{...o,v:(o.v||.12)*.3,rv:1});nt(f*5.4,d*.2,{...o,v:(o.v||.12)*.1})};
const ns=(d=.15,o={})=>{if(!S.sfx)return;try{const a=actx(),t=a.currentTime+(o.at||0),n=a.sampleRate*d|0,b=a.createBuffer(1,n,a.sampleRate),x=b.getChannelData(0);for(let i=0;i<n;i++)x[i]=Math.random()*2-1;const s=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();s.buffer=b;f.type='bandpass';f.Q.value=o.q||1.2;f.frequency.setValueAtTime(o.f||2000,t);if(o.to)f.frequency.exponentialRampToValueAtTime(o.to,t+d);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(o.v||.1,t+d*.2);g.gain.exponentialRampToValueAtTime(.0001,t+d);s.connect(f);f.connect(g);g.connect(MB);s.start(t)}catch(e){}};
