const pickVoice=()=>{if(!('speechSynthesis' in window))return;const vs=speechSynthesis.getVoices();VOICE=vs.find(v=>/^ko[-_]KR$/i.test(v.lang))||vs.find(v=>/^ko/i.test(v.lang))||vs.find(v=>/korean|yuna|sora|heami|seoyeon/i.test(v.name))||null};
