function speak(t,slow){if(!('speechSynthesis' in window))return toast('This browser can’t play speech.');pickVoice();if(!VOICE&&!warned++)toast('No Korean voice found, so audio may sound wrong. See Profile › Audio.');try{speechSynthesis.cancel()}catch(e){}setTimeout(()=>{try{const u=UT=new SpeechSynthesisUtterance(t);u.lang='ko-KR';if(VOICE)u.voice=VOICE;u.rate=slow?.55:.85;u.onerror=e=>{if(e.error!=='canceled'&&e.error!=='interrupted')toast('Audio was blocked ('+e.error+'). Tap the speaker again.')};speechSynthesis.speak(u);speechSynthesis.resume()}catch(e){toast('Audio failed to start.')}},70)}
