let cur,curU;
async function say(t,slow){try{cur&&cur.pause()}catch(e){}if(curU){URL.revokeObjectURL(curU);curU=null}try{const r=await fetch(aurl(t));if(!r.ok)throw new Error('missing');const b=await r.blob();curU=URL.createObjectURL(b);const a=cur=new Audio(curU);a.preservesPitch=true;a.playbackRate=slow?.6:1;await a.play()}catch(e){if(e&&e.name==='NotAllowedError')toast('Tap the speaker once more to allow audio.');else speak(t,slow)}}
