function home(){if(!S.name)return welcome();const td=day(),xt=S.log[td]||0,pct=Math.min(1,xt/S.goal),nx=(i=>i<0?ALLL.findIndex(l=>!S.done[l.id]):i)(ALLL.findIndex(l=>l.c==='k'&&!S.done[l.id])),st=liveStreak(),wk=[0,1,2,3,4,5,6].reduce((s,o)=>s+(S.log[day(o)]||0),0),md=mission();
const [m,msg]=nx<0?['celebrate','Every lesson is done. Keep reviewing in Practice.']:S.lessons===0?['excited','Start with the first lesson. It takes about five minutes.']:xt>=S.goal?['celebrate','Daily goal done.']:['happy',`${S.goal-xt} XP left for today’s goal.`];
const cal=[6,5,4,3,2,1,0].map(o=>`<div style="text-align:center"><div class="mut" style="font-size:12px">${new Date(Date.now()-o*864e5).toLocaleDateString('en',{weekday:'narrow'})}</div><div class="dot${S.log[day(o)]>0?' on':''}"></div></div>`).join('');
const mis=MIS.map((x,i)=>{const v=Math.min(x.v(),x.m),ok=x.v()>=x.m,cl=md.cl.includes(i);return `<div class="row" style="flex-wrap:nowrap;margin-bottom:8px"><div style="flex:1"><b>${x.t}</b><div class="row" style="gap:8px"><div class="bar"><i style="width:${100*v/x.m}%"></i></div><small class="mut">${v}/${x.m}</small></div></div>${cl?'<span>{{I:Check}}</span>':ok?`<button class="btn sm" data-a="claim" data-v="${i}">Claim {{I:Gem}}5</button>`:'<span class="mut">{{I:Gem}}5</span>'}</div>`}).join('');
return `<div class="wrap"><h1>안녕하세요, ${esc(S.name)}</h1>
<div class="card row">${bori(m,84)}<p style="flex:1;min-width:180px;font-weight:600">${msg}</p></div>
<div class="hero"><div style="min-width:0"><small>${nx<0?'All done':ALLL[nx].c==='k'?'Korean course':'Hangul course'}</small><h2>${nx<0?'Replay a lesson':esc(ALLL[nx].t)}</h2></div><button class="btn w" data-a="start" data-v="${nx<0?0:nx}">${nx<0?'REPLAY':'START'}</button></div>${S.known.length<10?`<div class="card row" style="justify-content:space-between;flex-wrap:nowrap"><div><b>New to Hangul?</b><p class="mut" style="margin:0">Learn the alphabet first. Korean words are easier once you can read them.</p></div><button class="btn g sm" data-a="go" data-v="hangul">Open Hangul</button></div>`:''}
<div class="grid g2"><div class="card row"><svg width="84" height="84" viewBox="0 0 84 84" role="img" aria-label="Daily goal ${xt} of ${S.goal} XP"><circle cx="42" cy="42" r="34" fill="none" stroke="var(--line)" stroke-width="9"/><circle class="rg" cx="42" cy="42" r="34" fill="none" stroke="var(--pri)" stroke-width="9" stroke-linecap="round" stroke-dasharray="${pct*213.6} 213.6" transform="rotate(-90 42 42)"/></svg><div><h2>${xt} / ${S.goal} XP</h2><span class="mut">Today’s goal</span></div></div>
<div class="card"><h2><span class="fl">{{I:Flame}}</span> ${st} day streak</h2><div class="grid" style="grid-template-columns:repeat(7,1fr)">${cal}</div></div></div>
<div class="card"><h2>Daily missions</h2>${mis}</div>
<div class="card row"><button class="btn c" data-a="prac" data-v="speed">{{I:Timer}} Speed round</button><button class="btn g" data-a="prac" data-v="mix">{{I:Repeat}} Mixed review</button></div>
<div class="card"><h2>This week</h2><div class="grid g2"><div><b>${wk}</b> <span class="mut">XP earned</span></div><div><b>${S.lessons}</b> <span class="mut">lessons completed</span></div><div><b>${S.known.length}</b> <span class="mut">letters learned</span></div><div><b>${S.words.length}</b> <span class="mut">words read</span></div></div></div>${demo}</div>`}
let pop=null;
function trail(ls,nx){const n=ls.length,gap=156,H=n*gap+130,xs=k=>50+25*Math.sin(k*.7),P=ls.map((_,k)=>[+xs(k).toFixed(1),k*gap+66]),dn=ls.filter(a=>S.done[a[0].id]).length,mid=n>>1;let h='',seg='';
ls.forEach(([l,i],k)=>{const d=S.done[l.id],lock=!S.open&&!l.first&&i>0&&!S.done[ALLL[i-1].id],cur=i===nx,[x,y]=P[k];
if(k<n-1){const a=P[k-1]||P[k],b=P[k],c=P[k+1],e=P[k+2]||c,c1=[b[0]+(c[0]-a[0])/6,b[1]+(c[1]-a[1])/6],c2=[c[0]-(e[0]-b[0])/6,c[1]-(e[1]-b[1])/6];seg+=`<path class="sg${d?' dn':''}" d="M${b[0]} ${b[1]}C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${c[0]} ${c[1]}"/>`}
h+=`<button class="nd ${d?'dn':lock?'lk':cur?'cur':''} ${x<50?'tl':'tr'}" style="left:${x}%;top:${y}px" data-a="${cur?'start':'node'}" data-v="${i}" data-t="${esc(l.t)}" aria-label="${esc(l.t)}"${lock?' aria-disabled="true"':''}>${cur?'<span class="go">START</span>':''}${lock?'{{I:Lock}}':d?'{{I:Check}}':KI[l.kind]}</button>`;
if(pop===i)h+=`<div class="pp" style="left:${Math.max(36,Math.min(64,x))}%;top:${y+50}px"><b>${esc(l.t)}</b><span>${d?'Best '+d.acc+'%':KN[l.kind]}</span><button class="btn sm" data-a="start" data-v="${i}">${d?'Practice again':'Start'}</button></div>`;
if(k===mid){const bx=x<50?78:22,s=Math.floor(dn*3/n);h+=`<div class="bk" style="left:${bx}%;top:${y}px">${bori(dn===n?'celebrate':'happy',78)}<div class="st">${[0,1,2].map(j=>`<span class="${j<s?'f':''}">{{I:Star}}</span>`).join('')}</div></div>`}});
return `<div class="trail" style="height:${H}px"><svg viewBox="0 0 100 ${H}" preserveAspectRatio="none" aria-hidden="true">${seg}</svg>${h}</div>`}
const grp=(arr,off)=>{const g=[];arr.forEach((l,i)=>(g[l.u]=g[l.u]||[]).push([l,i+off]));return g};
const GH=grp(LS,0),GK=grp(KS,LS.length),FH=LS.map((l,i)=>[l,i]),FK=KS.map((l,i)=>[l,i+LS.length]);
