function letters(){const t=a=>`<div class="grid g4">`+a.map(x=>`<button class="tile ${mst(x.ch)}${sel===x.ch?' on':''}" data-a="tile" data-v="${x.ch}">${x.ch}<small>${x.snd}</small></button>`).join('')+`</div>`,r=byCh[sel];
return `<div class="wrap"><h1>Hangul letters</h1><p class="mut">Tap a letter to hear it. The border shows how well you know it. English spellings are only rough.</p>${r?`<div class="card"><div class="big">${r.ch}</div><h2 style="text-align:center">Sounds like “${esc(r.snd)}”</h2><p>${esc(r.tip)}</p><div class="row"><button class="btn" data-a="say" data-v="${r.say}">{{I:Volume2}} Hear ${r.say}</button><button class="btn g" data-a="slow" data-v="${r.say}">{{I:Turtle}} Slow</button></div></div>`:''}<h2>Consonants</h2>${t(CI)}<h2 style="margin-top:18px">Vowels</h2>${t(VI)}<h2 style="margin-top:18px">Tense consonants</h2>${t(TI)}<h2 style="margin-top:18px">Compound vowels</h2>${t(XI)}<p class="mut note" style="margin-top:12px">${vinfo()}</p></div>`}
function build(){const s=comp(B.i,B.v,B.f),sn=x=>{const r=[...C,...T,...V,...X].find(y=>y[0]===x);return r?(r[1]==='silent'?'':r[1]):''},snd=sn(B.i)+sn(B.v)+(B.f?FS[B.f]||'':''),b=(k,x,lab)=>`<button class="tile${B[k]===x?' on':''}" style="font-size:24px;aspect-ratio:auto;padding:10px" data-a="bset" data-v="${k}${x}">${lab||x}</button>`;
return `<div class="wrap"><h1>Syllable builder</h1><p class="mut">Every Hangul block joins an initial consonant, a vowel, and an optional final consonant (batchim).</p><div class="card"><div class="big">${s}</div><p class="mut" style="text-align:center">${B.i} + ${B.v}${B.f?' + '+B.f:''} = ${s} · sounds like “${snd||'ah'}”</p><div class="row" style="justify-content:center"><button class="btn" data-a="say" data-v="${s}">{{I:Volume2}} Listen</button><button class="btn g" data-a="slow" data-v="${s}">{{I:Turtle}} Slow</button></div></div><h2>Initial consonant</h2><div class="grid g4">${[...IN].map(x=>b('i',x)).join('')}</div><h2 style="margin-top:18px">Vowel</h2><div class="grid g4">${[...VW].map(x=>b('v',x)).join('')}</div><h2 style="margin-top:18px">Final consonant</h2><div class="grid g4">${['','ㄱ','ㄴ','ㄷ','ㄹ','ㅁ','ㅂ','ㅇ'].map(x=>b('f',x,x||'none')).join('')}</div></div>`}
