let U=null,syncSt='',authErr='',busy=false,lastEm='',RANK={rows:null,err:'',tab:'week',busy:0},stm;
const wkXp=()=>[0,1,2,3,4,5,6].reduce((s,o)=>s+(S.log[day(o)]||0),0);
const upd=()=>{const e=$('#sync');if(e)e.textContent=syncSt};
function queueSync(){if(!U||!cloud.enabled)return;clearTimeout(stm);syncSt='Saving…';upd();stm=setTimeout(async()=>{try{await cloud.push(U.uid,S,{...meDoc(),week:wkXp(),at:Date.now()},S.pub);syncSt='Synced'}catch(e){syncSt='Sync failed: '+(e.code||e.message)}upd()},2000)}
const accLine=()=>U?`${esc(maskEmail(U.email)||'Signed in')} · ${esc(syncSt||'Synced')}`:cloud.enabled?'Not signed in. Progress is saved on this device only.':'Cloud sync is off (no Firebase keys found).';
function account(){const back='<button class="btn g sm" data-a="go" data-v="profile">Back</button>';
if(!cloud.enabled)return `<div class="wrap"><h1>Account</h1><div class="card"><p>Cloud sync is off because no Firebase keys were found.</p><p class="mut note">Add your keys to .env.local (see the README) to turn on accounts, sync and leaderboards. Until then progress is saved on this device only.</p></div>${back}</div>`;
if(U)return `<div class="wrap"><h1>Account</h1><div class="card"><p><b>${esc(maskEmail(U.email)||U.displayName||'Signed in')}</b></p><p class="mut" id="sync">${esc(syncSt)}</p><button class="btn c" data-a="out">Sign out</button></div>${back}</div>`;
const d=busy?' disabled':'';return `<div class="wrap"><h1>Sign in</h1><p class="mut">Sync progress across devices and join the leaderboard.</p><div class="card"><input id="em" class="inp" type="email" autocomplete="email" placeholder="Email" aria-label="Email" value="${esc(lastEm)}"><p></p><input id="pw" class="inp" type="password" autocomplete="current-password" placeholder="Password (6+ characters)" aria-label="Password"><p></p>${authErr?`<p role="alert" style="color:var(--cor);font-weight:600">${esc(authErr)}</p>`:''}<div class="row"><button class="btn" data-a="auth" data-v="in"${d}>Sign in</button><button class="btn g" data-a="auth" data-v="up"${d}>Create account</button></div><p></p><button class="btn g" data-a="auth" data-v="g"${d}>Continue with Google</button><p></p><button class="chip" data-a="auth" data-v="rst"${d}>Forgot password?</button>${busy?'<p class="mut">Working…</p>':''}</div>${back}</div>`}
async function loadRank(){if(RANK.busy)return;RANK.busy=1;RANK.err='';try{RANK.rows=await cloud.top()}catch(e){RANK.err='Couldn’t load the leaderboard: '+(e.code||e.message);RANK.rows=null}RANK.busy=0;if(!L)render()}
function rank(){if(!cloud.enabled)return `<div class="wrap"><h1>Leaderboard</h1><div class="card"><p>Leaderboards need Firebase. Add your keys (see the README) and sign in.</p></div></div>`;
if(!U)return `<div class="wrap"><h1>Leaderboard</h1><div class="card"><p>Sign in to see the rankings and appear on them.</p><button class="btn" data-a="go" data-v="account">Sign in</button></div></div>`;
if(RANK.rows===null&&!RANK.err)loadRank();
const wk=RANK.tab==='week',rows=(RANK.rows||[]).filter(r=>!wk||r.at>Date.now()-6048e5).sort((a,b)=>wk?b.week-a.week:b.xp-a.xp);
return `<div class="wrap"><h1>Leaderboard</h1><div>${chip('rank','week','Last 7 days',wk)}${chip('rank','all','All time',!wk)}</div>${RANK.err?`<div class="card"><p role="alert">${esc(RANK.err)}</p><button class="btn sm" data-a="rr">Retry</button></div>`:RANK.rows===null?'<div class="card mut">Loading…</div>':!rows.length?'<div class="card"><p>No one here yet. Finish a lesson to get on the board.</p></div>':rows.map((r,i)=>`<a class="card row rk" href="#u/${encodeURIComponent(r.u||'~'+r.id)}" style="flex-wrap:nowrap${r.id===U.uid?';border-color:var(--pri)':''}"><b class="rn">${i+1}</b><span style="flex:1;min-width:0">${esc(r.name||'Learner')}${r.u?` <small class="mut">@${esc(r.u)}</small>`:''}</span><b>${nn(wk?r.week:r.xp)} XP</b></a>`).join('')}${!S.pub?'<p class="mut note">You’re hidden from the leaderboard (Settings).</p>':''}</div>`}
async function loadUser(){if(PV.loading)return;PV.loading=true;try{PV.data=await cloud.getProfile(PV.h);if(!PV.data)PV.err='No public profile found for “'+PV.h.replace(/^~/,'')+'”.'}catch(e){PV.err='Couldn’t load this profile: '+(e.code||e.message)}PV.loading=false;if(!L)render()}
function userview(){const back='<button class="btn g sm" data-a="go" data-v="rank">Back to ranks</button>';
if(!cloud.enabled)return `<div class="wrap"><h1>Profile</h1><div class="card"><p>Profiles need Firebase to be set up.</p></div>${back}</div>`;
if(PV.err)return `<div class="wrap"><h1>Profile</h1><div class="card"><p role="alert">${esc(PV.err)}</p></div>${back}</div>`;
if(!PV.data){loadUser();return `<div class="wrap"><div class="card mut">Loading profile…</div></div>`}
return `<div class="wrap">${pcard(PV.data,false)}${pstats(PV.data)}${back}</div>`}
