async function writeMeta(){try{const c=await caches.open('bh-meta');await c.put('meta.json',new Response(JSON.stringify({rem:S.rem,last:S.last,streak:liveStreak(),xp:S.xp,goal:S.goal,today:S.log[day()]||0}),{headers:{'Content-Type':'application/json'}}));if(navigator.serviceWorker&&navigator.serviceWorker.controller)navigator.serviceWorker.controller.postMessage({type:'meta'})}catch(e){}}
