function scheduleRem(){clearTimeout(remT);if(!S.rem||!S.rem.on)return;const [h,m]=S.rem.t.split(':').map(Number),n=new Date(),t=new Date(n.getFullYear(),n.getMonth(),n.getDate(),h,m,0);if(t<=n)t.setDate(t.getDate()+1);remT=setTimeout(()=>{if(S.last!==day())notify('Keep your streak alive','A 5-minute lesson keeps your '+liveStreak()+'-day streak going.');scheduleRem()},Math.min(t-n,2147e6))}
